Translate the following GNU C++ code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++ code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;

#define LL long long
#define ULL unsigned LL
#define PII pair<int,int>
#define PB push_back
#define MP make_pair
#define INF 1000000000
#define MOD 1000000007

int shortest[15][15][15][15];
int cap[400][400];
char scien[20][20];
char reac[20][20];
int dx[] = {1, 0, -1, 0};
int dy[] = {0, 1, 0, -1};
int iteration = 3;
int visited[400];

int n, t;
int augment(int cnode, int dest, int bneck) {
    if (cnode == dest) return bneck;
    if (visited[cnode] == iteration) return 0;
    visited[cnode] = iteration;
    for (int i = 0; i <= dest; i++) {
        if (cap[cnode][i] > 0) {
            int flow = augment(i, dest, min(bneck, cap[cnode][i]));
            if (flow > 0) {
                cap[cnode][i] -= flow;
                cap[i][cnode] += flow;
                return flow;
            }
        }
    }
    return 0;
}

int getNode(int x, int y) {
    return (x - 1) * n + y - 1;
}

int reach[13][13], treach[13][13];

void expand(int val) {
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= n; j++)
            treach[i][j] = reach[i][j];

    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (treach[i][j] == val) {
                for (int k = 0; k < 4; k++) {
                    int ni = i + dx[k], nj = j + dy[k];
                    if (ni > 0 && nj > 0 && ni <= n && nj <= n && treach[ni][nj] < val && scien[ni][nj] != 'Y') {
                        reach[ni][nj] = val;
                    }
                }
            }
        }
    }
}

bool canReach(int sx, int sy, int tx, int ty, int ix, int iy) {
    memset(reach, 0, sizeof(reach));
    reach[sx][sy] = 1;
    reach[ix][iy] = 2;
    for (int iterCount = 0; iterCount < 100; iterCount++) {
        expand(1);
        if (reach[tx][ty] == 1) return true;
        expand(2);
        if (reach[tx][ty] == 2) return false;
    }
    return false;
}

int main() {
    int infx, infy;
    memset(shortest, 1, sizeof(shortest));
    cin >> n >> t;
    for (int i = 1; i <= n; i++) {
        scanf(" %s", scien[i] + 1);
        for (int j = 1; j <= n; j++) {
            shortest[i][j][i][j] = 0;
            if (scien[i][j] == 'Z') {
                infx = i; infy = j;
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        scanf(" %s", reac[i] + 1);
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            for (int k = 0; k < 4; k++) {
                int ni = i + dx[k], nj = j + dy[k];
                if (ni > 0 && ni <= n && nj > 0 && nj <= n) {
                    if (scien[i][j] != 'Y' && scien[ni][nj] != 'Y') {
                        shortest[i][j][ni][nj] = 1;
                    }
                }
            }
        }
    }
    for (int ki = 1; ki <= n; ki++) {
        for (int kj = 1; kj <= n; kj++) {
            for (int ii = 1; ii <= n; ii++) {
                for (int ij = 1; ij <= n; ij++) {
                    for (int ji = 1; ji <= n; ji++) {
                        for (int jj = 1; jj <= n; jj++) {
                            shortest[ii][ij][ji][jj] = min(
                                shortest[ii][ij][ji][jj],
                                shortest[ii][ij][ki][kj] + shortest[ki][kj][ji][jj]
                            );
                        }
                    }
                }
            }
        }
    }
    int src = n * n * 2 + 1;
    int dest = n * n * 2 + 2;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (isdigit(scien[i][j])) {
                cap[src][getNode(i, j)] = scien[i][j] - '0';
            }
            if (isdigit(reac[i][j])) {
                cap[n * n + getNode(i, j)][dest] = reac[i][j] - '0';
            }
            if (isdigit(scien[i][j])) {
                for (int ki = 1; ki <= n; ki++) {
                    for (int kj = 1; kj <= n; kj++) {
                        if (scien[i][j] > '0' && reac[ki][kj] > '0') {
                            if (isdigit(reac[ki][kj]) && shortest[i][j][ki][kj] <= t && canReach(i, j, ki, kj, infx, infy)) {
                                cap[getNode(i, j)][n * n + getNode(ki, kj)] = 1000;
                            }
                        }
                    }
                }
            }
        }
    }
    int totalFlow = 0, flowRet;
    while ((flowRet = augment(src, dest, 1000)) > 0) {
        totalFlow += flowRet;
        iteration++;
    }
    cout << totalFlow << endl;
    return 0;
}
